const raw = $input.first().json;
const msg = raw.message || (raw.callback_query && raw.callback_query.message) || null;
const cq = raw.callback_query || null;
const from = (cq && cq.from) || (msg && msg.from) || {};
const chat = (msg && msg.chat) || {};
const text = ((msg && msg.text) || '').trim();
const callback_data = (cq && cq.data) || '';
const callback_query_id = (cq && cq.id) || null;
let command = '';
if (text.startsWith('/')) {
  command = text.split(/\s+/)[0].split('@')[0].toLowerCase();
}
return [{
  json: {
    update_type: cq ? 'callback' : 'message',
    telegram_user_id: from.id || null,
    chat_id: chat.id || (from.id || null),
    text,
    command,
    callback_data,
    callback_query_id,
    from_username: from.username || null,
    from_name: [from.first_name, from.last_name].filter(Boolean).join(' ') || null,
  }
}];

/**
 * Telegram quiz helpers for psy_08.
 * Pure functions — embedded into n8n Code nodes and covered by node:test.
 */

const QUIZ_SIZE = 10;
const CHOICES = ['A', 'B', 'C', 'D'];

function hashSeed(str) {
  let h = 2166136261;
  const s = String(str || '');
  for (let i = 0; i < s.length; i += 1) {
    h ^= s.charCodeAt(i);
    h = Math.imul(h, 16777619);
  }
  return h >>> 0;
}

function mulberry32(seed) {
  let a = seed >>> 0;
  return function rng() {
    a = (a + 0x6d2b79f5) >>> 0;
    let t = a;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

function shuffle(arr, rng) {
  const out = arr.slice();
  for (let i = out.length - 1; i > 0; i -= 1) {
    const j = Math.floor(rng() * (i + 1));
    const tmp = out[i];
    out[i] = out[j];
    out[j] = tmp;
  }
  return out;
}

function lectureLabel(row) {
  const meta = row && row.source_meta;
  let folderPath = null;
  if (meta && typeof meta === 'object') {
    folderPath = meta.drive && meta.drive.folder_path;
  } else if (typeof meta === 'string' && meta.trim()) {
    try {
      const parsed = JSON.parse(meta);
      folderPath = parsed.drive && parsed.drive.folder_path;
    } catch (_e) {
      folderPath = null;
    }
  }
  if (Array.isArray(folderPath) && folderPath.length) {
    return String(folderPath[folderPath.length - 1]);
  }
  if (row && row.title && String(row.title).trim() && String(row.title) !== 'audio_16k.opus') {
    return String(row.title).trim();
  }
  return 'Лекция';
}

/**
 * Prefer unanswered questions, diversify by subtopic, fill to limit.
 * @param {Array<object>} candidates
 * @param {{limit?: number, seed?: string|number}} [opts]
 */
function selectQuizQuestions(candidates, opts = {}) {
  const limit = opts.limit == null ? QUIZ_SIZE : Number(opts.limit);
  const rng = mulberry32(hashSeed(opts.seed == null ? String(Date.now()) : opts.seed));
  const list = Array.isArray(candidates) ? candidates : [];
  const unanswered = list.filter((q) => !q.answered_before);
  const answered = list.filter((q) => q.answered_before);

  function diversify(pool) {
    const bySub = new Map();
    for (const q of shuffle(pool, rng)) {
      const key = String(q.subtopic_id || q.id);
      if (!bySub.has(key)) bySub.set(key, []);
      bySub.get(key).push(q);
    }
    const keys = shuffle([...bySub.keys()], rng);
    const out = [];
    let progressed = true;
    while (out.length < limit && progressed) {
      progressed = false;
      for (const key of keys) {
        const bucket = bySub.get(key);
        if (bucket && bucket.length) {
          out.push(bucket.shift());
          progressed = true;
          if (out.length >= limit) break;
        }
      }
    }
    return out;
  }

  let selected = diversify(unanswered);
  if (selected.length < limit) {
    const used = new Set(selected.map((q) => String(q.id)));
    const fill = diversify(answered.filter((q) => !used.has(String(q.id))));
    selected = selected.concat(fill).slice(0, limit);
  }
  return selected.slice(0, limit);
}

function escapeHtml(text) {
  return String(text == null ? '' : text)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;');
}

function choiceText(question, letter) {
  const key = `choice_${String(letter).toLowerCase()}`;
  return question[key] || '';
}

function formatQuestionMessage(question, index, total) {
  const n = index + 1;
  const lines = [
    `<b>Вопрос ${n} из ${total}</b>`,
    '',
    escapeHtml(question.stem),
    '',
    `<b>A.</b> ${escapeHtml(choiceText(question, 'A'))}`,
    `<b>B.</b> ${escapeHtml(choiceText(question, 'B'))}`,
    `<b>C.</b> ${escapeHtml(choiceText(question, 'C'))}`,
    `<b>D.</b> ${escapeHtml(choiceText(question, 'D'))}`,
  ];
  return lines.join('\n');
}

function inlineKeyboardRows(buttonsRows) {
  return {
    rows: buttonsRows.map((row) => ({
      row: {
        buttons: row.map((btn) => ({
          text: btn.text,
          additionalFields: { callback_data: btn.callback_data },
        })),
      },
    })),
  };
}

function choiceKeyboard(sessionId) {
  return inlineKeyboardRows([
    CHOICES.map((letter) => ({
      text: letter,
      callback_data: `ans:${sessionId}:${letter}`,
    })),
  ]);
}

function nextKeyboard(sessionId) {
  return inlineKeyboardRows([[{ text: 'Дальше', callback_data: `next:${sessionId}` }]]);
}

function coursesKeyboard(courses) {
  return inlineKeyboardRows(
    (courses || []).map((c) => [
      {
        text: String(c.title || 'Курс').slice(0, 60),
        callback_data: `course:${c.id}`,
      },
    ]),
  );
}

function lecturesKeyboard(lectures) {
  return inlineKeyboardRows(
    (lectures || []).map((l) => [
      {
        text: lectureLabel(l).slice(0, 60),
        callback_data: `lecture:${l.id}`,
      },
    ]),
  );
}

function explanationFor(question, chosen) {
  const map = question.choice_explanations;
  if (map && typeof map === 'object') {
    const fromChoice = map[chosen] || map[String(chosen).toLowerCase()];
    if (fromChoice) return String(fromChoice);
  }
  if (question.explanation) return String(question.explanation);
  return '';
}

function anchorLine(question) {
  if (question.source_kind === 'term') {
    const term = question.term_canonical || 'термин';
    const def = question.term_definition || '';
    if (def) {
      return `Термин: <b>${escapeHtml(term)}</b> — ${escapeHtml(def)}`;
    }
    return `Термин: <b>${escapeHtml(term)}</b>`;
  }
  const thesis = question.thesis || '';
  if (thesis) {
    return `Тезис: ${escapeHtml(thesis)}`;
  }
  return '';
}

function formatFeedback({ correct, chosen, question }) {
  const right = String(question.correct_choice || '').toUpperCase();
  const pick = String(chosen || '').toUpperCase();
  const expl = explanationFor(question, pick);
  const lines = [];
  if (correct) {
    lines.push('<b>Верно</b>');
  } else {
    lines.push('<b>Неверно</b>');
    lines.push(`Правильный вариант: <b>${escapeHtml(right)}</b>. ${escapeHtml(choiceText(question, right))}`);
  }
  if (expl) {
    lines.push('');
    lines.push(escapeHtml(expl));
  }
  const anchor = anchorLine(question);
  if (anchor) {
    lines.push('');
    lines.push(anchor);
  }
  return lines.join('\n');
}

function formatSummary({ correctCount, total, missSubtopics }) {
  const lines = [`<b>Итог: ${correctCount}/${total}</b>`];
  const misses = (missSubtopics || []).filter(Boolean);
  if (misses.length) {
    lines.push('');
    lines.push('Подтемы с ошибками:');
    for (const title of misses) {
      lines.push(`• ${escapeHtml(title)}`);
    }
  } else {
    lines.push('');
    lines.push('Ошибок по подтемам нет — отличная сессия.');
  }
  lines.push('');
  lines.push('Новая сессия: /quiz');
  return lines.join('\n');
}

function ratingForAnswer(correct) {
  return correct ? 3 : 1;
}

function computeResponseMs(askedAt, now) {
  if (!askedAt) return null;
  const start = new Date(askedAt).getTime();
  const end = now ? new Date(now).getTime() : Date.now();
  if (!Number.isFinite(start) || !Number.isFinite(end) || end < start) return null;
  return Math.max(0, Math.round(end - start));
}

function parseCallback(data) {
  const raw = String(data || '');
  if (raw.startsWith('course:')) {
    return { kind: 'course', courseId: raw.slice(7) };
  }
  if (raw.startsWith('lecture:')) {
    return { kind: 'lecture', lectureId: raw.slice(8) };
  }
  if (raw.startsWith('ans:')) {
    const parts = raw.split(':');
    if (parts.length !== 3) return { kind: 'unknown', raw };
    return {
      kind: 'answer',
      sessionId: parts[1],
      choice: String(parts[2] || '').toUpperCase(),
    };
  }
  if (raw.startsWith('next:')) {
    return { kind: 'next', sessionId: raw.slice(5) };
  }
  return { kind: 'unknown', raw };
}

function uniquePreserve(list) {
  const out = [];
  const seen = new Set();
  for (const item of list || []) {
    const key = String(item);
    if (!key || seen.has(key)) continue;
    seen.add(key);
    out.push(item);
  }
  return out;
}

function tallyAnswer({ session, correct, subtopicTitle }) {
  const correctCount = Number(session.correct_count || 0) + (correct ? 1 : 0);
  const answeredCount = Number(session.answered_count || 0) + 1;
  const miss = uniquePreserve(
    correct ? session.miss_subtopics || [] : [...(session.miss_subtopics || []), subtopicTitle].filter(Boolean),
  );
  return { correctCount, answeredCount, missSubtopics: miss };
}

const norm = $('Run — Normalize').first().json;
const userRow = $input.first().json;
const allowed = userRow.allowed === true || userRow.allowed === 't' || userRow.allowed === true;
const userId = userRow.user_id || null;
const displayName = userRow.display_name || null;
const session = {
  id: userRow.session_id || null,
  status: userRow.session_status || null,
  lecture_id: userRow.session_lecture_id || null,
  question_ids: userRow.session_question_ids || [],
  cursor: Number(userRow.session_cursor || 0),
  current_question_id: userRow.session_current_question_id || null,
  asked_at: userRow.session_asked_at || null,
  correct_count: Number(userRow.session_correct_count || 0),
  answered_count: Number(userRow.session_answered_count || 0),
  miss_subtopics: userRow.session_miss_subtopics || [],
  last_callback_id: userRow.session_last_callback_id || null,
};
if (typeof session.question_ids === 'string') {
  try { session.question_ids = JSON.parse(session.question_ids); } catch (_e) { session.question_ids = []; }
}
if (typeof session.miss_subtopics === 'string') {
  try { session.miss_subtopics = JSON.parse(session.miss_subtopics); } catch (_e) { session.miss_subtopics = []; }
}

const base = {
  chat_id: norm.chat_id,
  telegram_user_id: norm.telegram_user_id,
  callback_query_id: norm.callback_query_id,
  user_id: userId,
  display_name: displayName,
  session,
  has_callback: !!norm.callback_query_id,
};

function reply(action, text, extra = {}) {
  return [{ json: { ...base, action, out_text: text, keyboard: null, ...extra } }];
}
function replyKb(action, text, keyboard, extra = {}) {
  return [{ json: { ...base, action, out_text: text, keyboard, ...extra } }];
}

if (!norm.telegram_user_id || !norm.chat_id) {
  return reply('noop', '');
}

if (!allowed) {
  if (norm.command === '/start' || norm.command === '/quiz' || norm.command === '/help' || norm.command === '/stop') {
    return reply('pending_reg',
      'Здравствуйте! Бот пока доступен только участникам курса. Мы получили ваш запрос на доступ — дождитесь подтверждения и напишите /start ещё раз.');
  }
  if (norm.update_type === 'callback') {
    return reply('noop', '');
  }
  return reply('refuse',
    'Извините, этот бот доступен только студентам курса. Если вы Наталья или Сергей — напишите Сергею для доступа.');
}

const openStatuses = new Set(['picking_course','picking_lecture','active','awaiting_next']);
const hasOpen = !!(session.id && openStatuses.has(session.status));

if (norm.command === '/start') {
  const name = displayName || 'студент';
  return reply('welcome',
    `Привет, ${name}!\n\nКоманды:\n/quiz — квиз по лекции (10 вопросов)\n/stop — прервать текущую сессию\n/help — справка`);
}

if (norm.command === '/help') {
  return reply('help',
    'Квиз без подсказок модели: вопросы уже в базе.\n/quiz — выбрать курс и лекцию\n/stop — остановить сессию\nОтветы — кнопками A–D.');
}

if (norm.command === '/stop') {
  if (!hasOpen) {
    return reply('stop_idle', 'Активной сессии нет. Начните новую: /quiz');
  }
  return reply('stop', 'Сессию остановил. Когда будете готовы — /quiz', { stop_session_id: session.id });
}

if (norm.command === '/quiz') {
  if (hasOpen && (session.status === 'active' || session.status === 'awaiting_next')) {
    return reply('busy', 'У вас уже есть активная сессия. Завершите её или отправьте /stop.');
  }
  return reply('pick_course', 'Выберите курс:');
}

if (norm.update_type === 'callback') {
  if (session.last_callback_id && norm.callback_query_id && session.last_callback_id === norm.callback_query_id) {
    return reply('noop', '');
  }
  const cb = parseCallback(norm.callback_data);
  if (cb.kind === 'course') {
    return reply('pick_lecture', 'Выберите лекцию:', { course_id: cb.courseId });
  }
  if (cb.kind === 'lecture') {
    if (hasOpen && (session.status === 'active' || session.status === 'awaiting_next')) {
      return reply('busy', 'У вас уже есть активная сессия. /stop — сбросить.');
    }
    return reply('start_quiz', '', { lecture_id: cb.lectureId });
  }
  if (cb.kind === 'answer') {
    if (!hasOpen || session.status !== 'active' || String(session.id) !== String(cb.sessionId)) {
      return reply('stale', '');
    }
    if (!['A','B','C','D'].includes(cb.choice)) {
      return reply('stale', '');
    }
    return reply('answer', '', { choice: cb.choice, session_id: session.id });
  }
  if (cb.kind === 'next') {
    if (!hasOpen || String(session.id) !== String(cb.sessionId)) {
      return reply('stale', '');
    }
    if (session.status !== 'awaiting_next') {
      return reply('stale', '');
    }
    return reply('next', '', { session_id: session.id });
  }
  return reply('stale', '');
}

return reply('help',
  'Не понял сообщение. Команды: /quiz, /stop, /help');

